  ConsumerState<AllTransactionsV2View> createState() =>
      _AllTransactionsV2ViewState();
}

class _AllTransactionsV2ViewState extends ConsumerState<AllTransactionsV2View> {
  late final String walletId;

  late final TextEditingController _searchController;
  final searchFieldFocusNode = FocusNode();

  late final PagedTransactions _paged;
  Timer? _searchDebounce;

  @override
  void initState() {
    walletId = widget.walletId;
    _searchController = TextEditingController();
    super.initState();
    _paged = PagedTransactions(
      isar: ref.read(mainDBProvider).isar,
      walletId: walletId,
      where: _predicate(),
    )..addListener(_onPagedChanged);
    ref.listenManual(
      transactionFilterProvider,
      (_, _) => _paged.setWhere(_predicate()),
    );
  }

  void _onPagedChanged() {
    if (mounted) setState(() {});
  }

  void _setSearch(String value) {
    _searchString = value;
    _searchDebounce?.cancel();
    _searchDebounce = Timer(
      const Duration(milliseconds: 250),
      () => _paged.setWhere(_predicate()),
    );
  }

  @override
  void dispose() {
    _searchDebounce?.cancel();
    _paged
      ..removeListener(_onPagedChanged)
      ..dispose();
    _searchController.dispose();
    searchFieldFocusNode.dispose();
    super.dispose();
  }

  /// Rows matching the filter and the search text; null for all rows.
  bool Function(TransactionV2 tx)? _predicate() {
    final criteria = ref.read(transactionFilterProvider);
    final text = _searchString.toLowerCase();
    if (criteria == null && text.isEmpty) return null;
    final contacts = ref.read(addressBookServiceProvider).contacts;
    final notes = {
      for (final n
          in ref
              .read(mainDBProvider)
              .isar
              .transactionNotes
              .where()
              .walletIdEqualTo(walletId)
              .findAllSync())
        n.txid: n.value,
    };
    return (tx) =>
        (criteria == null || _matchesFilter(tx, criteria, contacts, notes)) &&
        _isKeywordMatch(tx, text, contacts, notes);
  }

  bool _matchesFilter(
    TransactionV2 tx,
    TransactionFilter filter,
    List<ContactEntry> contacts,
    Map<String, String> notes,
  ) {
    {
      final categories = filter.pivxCategories;
      if (categories != null) {
        if (!PivxTxCategory.allOf(tx).any(categories.contains)) return false;
      } else {
        if (!filter.sent && !filter.received) {
          return false;
        }

        if (filter.received &&
            !filter.sent &&
            tx.type == TransactionType.outgoing) {
          return false;
        }

        if (filter.sent &&
            !filter.received &&
            tx.type == TransactionType.incoming) {
          return false;
        }
      }

      if (filter.amount != null && _txAmount(tx) != filter.amount) {
        return false;
      }

      final date = DateTime.fromMillisecondsSinceEpoch(tx.timestamp * 1000);
      if ((filter.to != null &&
              date.millisecondsSinceEpoch >
                  filter.to!.millisecondsSinceEpoch) ||
          (filter.from != null &&
              date.millisecondsSinceEpoch <
                  filter.from!.millisecondsSinceEpoch)) {
        return false;
      }

      return _isKeywordMatch(tx, filter.keyword.toLowerCase(), contacts, notes);
    }
  }

  bool _isKeywordMatch(
    TransactionV2 tx,
    String keyword,
    List<ContactEntry> contacts,
    Map<String, String> notes,
  ) {
    if (keyword.isEmpty) {
      return true;
    }

    bool contains = false;

    // check if address book name contains
    contains |= contacts
        .where(
          (e) =>
              e.addresses
                  .map((e) => e.address)
                  .toSet()
                  .intersection(tx.associatedAddresses())
                  .isNotEmpty &&
              e.name.toLowerCase().contains(keyword),
        )
        .isNotEmpty;

    // check if address contains
    contains |= tx
        .associatedAddresses()
        .where((e) => e.toLowerCase().contains(keyword))
        .isNotEmpty;

    // check if note contains
    contains |= notes[tx.txid]?.toLowerCase().contains(keyword) ?? false;

    // check if txid contains
    contains |= tx.txid.toLowerCase().contains(keyword);

    // check if subType contains
    contains |= tx.subType.name.toLowerCase().contains(keyword);

    // check if txType contains
    contains |= tx.type.name.toLowerCase().contains(keyword);

    // check if date contains
    contains |= Format.extractDateFrom(tx.timestamp)
        .toLowerCase()
        .contains(keyword);

    // on chain / shielded memo
    contains |= tx.onChainNote?.toLowerCase().contains(keyword) ?? false;

    // PIVX type ("staking", "masternode", "shield", ...)
    contains |= PivxTxCategory.allOf(tx)
        .any((c) => c.label.toLowerCase().contains(keyword));

    // amount: "1.2" finds 1.2, 1.25, 11.2, ...
    final number = keyword.replaceAll(",", ".");
    if (double.tryParse(number) != null) {
      contains |= _txAmount(tx).decimal.toString().contains(number);
    }

    return contains;
  }

  /// The amount shown for [tx] in the history.
  Amount _txAmount(TransactionV2 tx) {
    final digits = ref.read(pWalletCoin(walletId)).fractionDigits;
    return tx.type == TransactionType.outgoing
        ? tx.getAmountSentFromThisWallet(
            fractionDigits: digits,
            subtractFee: true,
          )
        : tx.getAmountReceivedInThisWallet(fractionDigits: digits);
  }

  String _searchString = "";

  /// Month headers and transactions, flattened so the list builds only
  /// the visible rows.
  List<_Row> _rows(List<TransactionV2> transactions) {
    final rows = <_Row>[];
    String? month;
    for (int i = 0; i < transactions.length; i++) {
      final tx = transactions[i];
      final date = DateTime.fromMillisecondsSinceEpoch(tx.timestamp * 1000);
      final label = DateFormat.yMMMM(l10n.localeName).format(date);
      final first = label != month;
      if (first) {
        rows.add((header: label, tx: null, first: rows.isEmpty, last: false));
        month = label;
      }
      final next = i + 1 < transactions.length ? transactions[i + 1] : null;
      final nextDate = next == null
          ? null
          : DateTime.fromMillisecondsSinceEpoch(next.timestamp * 1000);
      final last =
          nextDate == null ||
          nextDate.month != date.month ||
          nextDate.year != date.year;
      rows.add((header: null, tx: tx, first: first, last: last));
    }
    return rows;
  }

  Widget _txRow(BuildContext context, _Row row, bool isDesktop) {
    final tx = row.tx!;
    final radius = Radius.circular(Constants.size.circularBorderRadius);
    final child = isDesktop
        ? Padding(
            padding: const EdgeInsets.all(4),
            child: DesktopTransactionCardRow(
              key: Key("transactionCard_key_${tx.txid}"),
              transaction: tx,
              walletId: walletId,
            ),
          )
        : TransactionCardV2(
            // Content key: the card keeps its transaction in its state.
            key: Key(
              "transactionCard_key_${tx.txid}${tx.height}"
              "${tx.otherData.hashCode}",
            ),
            transaction: tx,
          );
    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: 4),
      child: Container(
        decoration: BoxDecoration(
          color: Theme.of(context).extension<StackColors>()!.popupBG,
          borderRadius: BorderRadius.only(
            topLeft: row.first ? radius : Radius.zero,
            topRight: row.first ? radius : Radius.zero,
            bottomLeft: row.last ? radius : Radius.zero,
            bottomRight: row.last ? radius : Radius.zero,
          ),
        ),
        child: Column(
          children: [
            if (isDesktop && !row.first)
              Container(
                height: 1,
                color: Theme.of(context).extension<StackColors>()!.background,
              ),
            child,
          ],
        ),
      ),
    );
  }

  Widget _list(BuildContext context, bool isDesktop) {
    if (!_paged.loaded) return const LoadingIndicator();
    final rows = _rows(_paged.items);
    return ListView.builder(
      primary: isDesktop ? false : null,
      itemCount: rows.length + (_paged.hasMore ? 1 : 0),
      itemBuilder: (context, index) {
        if (index >= rows.length - 10 && _paged.hasMore) {
          unawaited(_paged.loadMore());
        }
        if (index == rows.length) {
          return const Padding(
            padding: EdgeInsets.all(16),
            child: LoadingIndicator(height: 30, width: 30),
          );
        }
        final row = rows[index];
        if (row.header != null) {
          return Padding(
            padding: EdgeInsets.fromLTRB(4, row.first ? 4 : 16, 4, 12),
            child: Text(row.header!, style: STextStyles.smallMed12(context)),
          );
        }
        return _txRow(context, row, isDesktop);
      },
    );
  }

