class TransactionFilterOptionBar extends ConsumerStatefulWidget {
  const TransactionFilterOptionBar({super.key});

  @override
  ConsumerState<TransactionFilterOptionBar> createState() =>
      _TransactionFilterOptionBarState();
}

class _TransactionFilterOptionBarState
    extends ConsumerState<TransactionFilterOptionBar> {
  final List<TransactionFilterOptionBarItem> items = [];
  TransactionFilter? _filter;

  /// [copyWith] can't set a field back to null, so rebuild without it.
  TransactionFilter _without(
    TransactionFilter f, {
    bool to = false,
    bool from = false,
    bool amount = false,
    bool categories = false,
  }) => TransactionFilter(
    sent: f.sent,
    received: f.received,
    from: from ? null : f.from,
    to: to ? null : f.to,
    amount: amount ? null : f.amount,
    keyword: f.keyword,
    pivxCategories: categories ? null : f.pivxCategories,
  );

  void _remove(String label, TransactionFilter Function(TransactionFilter) f) {
    items.removeWhere((e) => e.label == label);
    final current = ref.read(transactionFilterProvider);
    if (items.isEmpty || current == null) {
      ref.read(transactionFilterProvider.notifier).state = null;
    } else {
      ref.read(transactionFilterProvider.notifier).state = f(current);
      setState(() {});
    }
  }

  @override
  void initState() {
    _filter = ref.read(transactionFilterProvider);

    if (_filter != null) {
      final categories = _filter!.pivxCategories;
      if (categories != null &&
          categories.length < PivxTxCategory.values.length) {
        final label = categories.map((e) => e.label).join(", ");
        items.add(
          TransactionFilterOptionBarItem(
            label: label,
            onPressed: (_) =>
                _remove(label, (f) => _without(f, categories: true)),
          ),
        );
      }
      if (_filter!.sent && categories == null) {
        final label = l10n.txSent;
        final item = TransactionFilterOptionBarItem(
          label: label,
          onPressed: (s) {
            items.removeWhere((e) => e.label == label);
            if (items.isEmpty) {
              ref.read(transactionFilterProvider.notifier).state = null;
            } else {
              ref.read(transactionFilterProvider.notifier).state = ref
                  .read(transactionFilterProvider)
                  ?.copyWith(sent: false);
              setState(() {});
            }
          },
        );
        items.add(item);
      }
      if (_filter!.received && categories == null) {
        final label = l10n.txReceived;
        final item = TransactionFilterOptionBarItem(
          label: label,
          onPressed: (s) {
            items.removeWhere((e) => e.label == label);
            if (items.isEmpty) {
              ref.read(transactionFilterProvider.notifier).state = null;
            } else {
              ref.read(transactionFilterProvider.notifier).state = ref
                  .read(transactionFilterProvider)
                  ?.copyWith(received: false);
              setState(() {});
            }
          },
        );
        items.add(item);
      }

      if (_filter!.from != null) {
        final label = l10n.txFromDate(
          _filter!.from!.toString().split(" ").first,
        );
        items.add(
          TransactionFilterOptionBarItem(
            label: label,
            onPressed: (_) => _remove(label, (f) => _without(f, from: true)),
          ),
        );
      }
      if (_filter!.to != null) {
        final label = l10n.txToDate(_filter!.to!.toString().split(" ").first);
        items.add(
          TransactionFilterOptionBarItem(
            label: label,
            onPressed: (_) => _remove(label, (f) => _without(f, to: true)),
          ),
        );
      }

      if (_filter!.amount != null) {
        final label = _filter!.amount!.decimal.toString();
        items.add(
          TransactionFilterOptionBarItem(
            label: label,
            onPressed: (_) => _remove(label, (f) => _without(f, amount: true)),
          ),
        );
      }
      if (_filter!.keyword.isNotEmpty) {
        final label = _filter!.keyword;
        final item = TransactionFilterOptionBarItem(
          label: label,
          onPressed: (s) {
            items.removeWhere((e) => e.label == label);
            if (items.isEmpty) {
              ref.read(transactionFilterProvider.notifier).state = null;
            } else {
              ref.read(transactionFilterProvider.notifier).state = ref
                  .read(transactionFilterProvider)
                  ?.copyWith(keyword: "");
              setState(() {});
            }
          },
        );
        items.add(item);
      }
    }

    super.initState();
  }

  @override
  Widget build(BuildContext context) {
    return SizedBox(
      height: 32,
      child: ListView.separated(
        primary: false,
        scrollDirection: Axis.horizontal,
        shrinkWrap: true,
        itemCount: items.length,
        separatorBuilder: (_, __) => const SizedBox(width: 16),
        itemBuilder: (context, index) => items[index],
      ),
    );
  }
}

