class _DesktopTransactionCardRowState
    extends ConsumerState<DesktopTransactionCardRow> {
  late final TransactionV2 _transaction;
  late final String walletId;
  late final int minConfirms;

  String whatIsIt(TransactionV2 tx, int height) => tx.statusLabel(
    currentChainHeight: height,
    minConfirms: minConfirms,
    minCoinbaseConfirms: ref
        .read(pWallets)
        .getWallet(widget.walletId)
        .cryptoCurrency
        .minCoinbaseConfirms,
  );

  @override
  void initState() {
    walletId = widget.walletId;
    minConfirms = ref
        .read(pWallets)
        .getWallet(widget.walletId)
        .cryptoCurrency
        .minConfirms;
    _transaction = widget.transaction;

    super.initState();
  }

  @override
  Widget build(BuildContext context) {
    final locale = ref.watch(
      localeServiceChangeNotifierProvider.select((value) => value.locale),
    );

    final baseCurrency = ref.watch(
      prefsChangeNotifierProvider.select((value) => value.currency),
    );

    final coin = ref.watch(pWalletCoin(walletId));

    Decimal? price;
    if (ref.watch(
      prefsChangeNotifierProvider.select((value) => value.externalCalls),
    )) {
      price = ref.watch(
        priceAnd24hChangeNotifierProvider.select(
          (value) => value.getPrice(coin)?.value,
        ),
      );
    }

    late final String prefix;
    if (Util.isDesktop) {
      if (_transaction.type == TransactionType.outgoing) {
        prefix = "-";
      } else if (_transaction.type == TransactionType.incoming) {
        prefix = "+";
      } else {
        prefix = "";
      }
    } else {
      prefix = "";
    }

    final currentHeight = ref.watch(pWalletChainHeight(walletId));

    final Amount amount;
    final fractionDigits = coin.fractionDigits;
    switch (_transaction.type) {
      case TransactionType.outgoing:
      case TransactionType.unknown:
        amount = _transaction.getAmountSentFromThisWallet(
          fractionDigits: fractionDigits,
          subtractFee: true,
        );
        break;

      case TransactionType.incoming:
      case TransactionType.sentToSelf:
        amount = _transaction.getAmountReceivedInThisWallet(
          fractionDigits: fractionDigits,
        );
        break;
    }

    return Material(
      color: Theme.of(context).extension<StackColors>()!.popupBG,
      elevation: 0,
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.circular(
          Constants.size.circularBorderRadius,
        ),
      ),
      child: RawMaterialButton(
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(
            Constants.size.circularBorderRadius,
          ),
        ),
        onPressed: () async {
          if (Util.isDesktop) {
            await showDialog<void>(
              context: context,
              builder: (context) => DesktopDialog(
                maxHeight: MediaQuery.of(context).size.height - 64,
                maxWidth: 640,
                child: tvd.TransactionV2DetailsView(
                  transaction: _transaction,
                  coin: coin,
                  walletId: walletId,
                ),
              ),
            );
          } else {
            unawaited(
              Navigator.of(context).pushNamed(
                tvd.TransactionV2DetailsView.routeName,
                arguments: (tx: _transaction, coin: coin, walletId: walletId),
              ),
            );
          }
        },
        child: Padding(
          padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 16),
          child: Row(
            children: [
              TxIcon(
                transaction: _transaction,
                currentHeight: currentHeight,
                coin: coin,
              ),
              const SizedBox(width: 12),
              Expanded(
                flex: 3,
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      whatIsIt(_transaction, currentHeight),
                      style: STextStyles.desktopTextExtraExtraSmall(context)
                          .copyWith(
                            color: Theme.of(context)
                                .extension<StackColors>()!
                                .textDark,
                          ),
                    ),
                    if (_transaction.pivxAlsoLabel != null)
                      Text(
                        "+ ${_transaction.pivxAlsoLabel}",
                        style: STextStyles.label(context),
                      ),
                  ],
                ),
              ),
              if (kDebugMode)
                Expanded(
                  flex: 3,
                  child: Text(
                    _transaction.subType.name,
                    style: STextStyles.label(context),
                  ),
                ),
              Expanded(
                flex: 4,
                child: Text(
                  Format.extractDateFrom(_transaction.timestamp),
                  style: STextStyles.label(context),
                ),
              ),
              Expanded(
                flex: 6,
                child: Builder(
                  builder: (context) {
                    final formattedAmount = ref
                        .watch(pAmountFormatter(coin))
                        .format(amount);

                    return Text(
                      "$prefix$formattedAmount",
                      style: STextStyles.desktopTextExtraExtraSmall(context)
                          .copyWith(
                            color: Theme.of(context)
                                .extension<StackColors>()!
                                .textDark,
                          ),
                    );
                  },
                ),
              ),
              if (price != null)
                Expanded(
                  flex: 4,
                  child: Builder(
                    builder: (context) {
                      final formattedFiat = (amount.decimal * price!)
                          .toAmount(fractionDigits: 2)
                          .fiatString(locale: locale);

                      return Text(
                        "$prefix$formattedFiat $baseCurrency",
                        style: STextStyles.desktopTextExtraExtraSmall(context),
                      );
                    },
                  ),
                ),
              SvgPicture.asset(
                Assets.svg.circleInfo,
                width: 20,
                height: 20,
                color: Theme.of(context)
                    .extension<StackColors>()!
                    .textSubtitle2,
              ),
            ],
          ),
        ),
      ),
    );
  }
}
